Use `URLSession` for the download and `@concurrent` for synchronous parsing. The model inherits main-actor isolation from the app target, so it can update its published state directly after each `await`.

```swift
import Combine
import Foundation

final class FeedModel: ObservableObject {
    @Published private(set) var items: [Item] = []
    @Published private(set) var isLoading = false
    @Published private(set) var error: (any Error)?

    private let feedURL: URL

    init(feedURL: URL) {
        self.feedURL = feedURL
    }

    func load() async {
        guard !isLoading else { return }
        isLoading = true
        error = nil
        defer { isLoading = false }

        do {
            let (data, response) = try await URLSession.shared.data(from: feedURL)
            if let http = response as? HTTPURLResponse,
               !(200..<300).contains(http.statusCode) {
                throw URLError(.badServerResponse)
            }

            try Task.checkCancellation()
            let parsed = try await Self.parse(data)
            try Task.checkCancellation()
            items = parsed
        } catch {
            // URLSession may report cancellation as URLError.cancelled.
            if !Task.isCancelled {
                self.error = error
            }
        }
    }

    @concurrent
    private static func parse(_ data: Data) async throws -> [Item] {
        Parser.parse(data)
    }
}
```

If `Parser` and `Item` are declared in the same main-actor-by-default target, opt the parser out of main-actor isolation (`nonisolated enum Parser`, for example) and make `Item` a `Sendable` value type (`nonisolated struct Item: Sendable`, with sendable stored properties). The parser must be safe to run off the main actor, and its result must be safe to transfer back. If `Parser.parse` throws, use `try Parser.parse(data)` in the wrapper.

In SwiftUI, call it with `.task { await model.load() }` so the view owns the task’s lifetime. `URLSession` already suspends during network I/O; `@concurrent` is for the CPU-bound parse, not the download.

Keep the model on the main actor, fetch with `URLSession`, and use Swift 6.2’s `@concurrent` to run the synchronous parser off the main actor. `URLSession.data(from:)` already suspends during the fetch, so it doesn’t need a background queue.

```swift
import Combine
import Foundation

@MainActor
final class FeedModel: ObservableObject {
    @Published private(set) var items: [Item] = []
    @Published private(set) var isLoading = false
    @Published private(set) var errorMessage: String?

    private let feedURL: URL

    init(feedURL: URL) {
        self.feedURL = feedURL
    }

    func load() async {
        guard !isLoading else { return }

        isLoading = true
        errorMessage = nil
        defer { isLoading = false }

        do {
            let (data, response) = try await URLSession.shared.data(from: feedURL)
            if let http = response as? HTTPURLResponse,
               !(200..<300).contains(http.statusCode) {
                throw URLError(.badServerResponse)
            }

            try Task.checkCancellation()
            let parsed = await Self.parseOffMain(data)
            try Task.checkCancellation()

            items = parsed
        } catch {
            if !Task.isCancelled {
                errorMessage = error.localizedDescription
            }
        }
    }

    @concurrent
    private static func parseOffMain(_ data: Data) async -> [Item] {
        Parser.parse(data)
    }
}
```

Two details matter with main-actor-by-default:

- **The parser must also be nonisolated.** If `Parser` is defined in this target and has no main-actor dependencies, declare it `nonisolated` (for example, `nonisolated enum Parser`). The `@concurrent` wrapper does not change the isolation of code it calls.
- **`Item` must be `Sendable`** because the parsed array crosses back to the main actor. For a value type with sendable fields, declare the conformance on `Item` itself.

In SwiftUI, call it with `.task { await model.load() }` so cancellation follows the view’s lifetime. The cancellation check after parsing prevents a cancelled load from publishing results; it does not interrupt a synchronous parse already in progress.

Use an `async` `load()` and `URLSession` for the download. Keep the model main-actor-isolated, and use Swift 6.2’s `@concurrent` for synchronous parsing so it doesn’t block the UI.

```swift
import Combine
import Foundation

// Item must conform to Sendable because the parsed values cross
// from the concurrent parser back to the main actor.
final class FeedModel: ObservableObject {
    @Published private(set) var items: [Item] = []
    @Published private(set) var isLoading = false
    @Published private(set) var loadError: (any Error)?

    private let feedURL: URL

    init(feedURL: URL) {
        self.feedURL = feedURL
    }

    func load() async {
        guard !isLoading else { return }
        isLoading = true
        loadError = nil
        defer { isLoading = false }

        do {
            let (data, response) = try await URLSession.shared.data(from: feedURL)
            if let http = response as? HTTPURLResponse,
               !(200..<300).contains(http.statusCode) {
                throw URLError(.badServerResponse)
            }

            try Task.checkCancellation()
            let parsed = await parseFeed(data)
            try Task.checkCancellation()
            items = parsed
        } catch {
            // URLSession can report cancellation as URLError.cancelled.
            guard !Task.isCancelled else { return }
            loadError = error
        }
    }
}

@concurrent
private func parseFeed(_ data: Data) async -> [Item] {
    Parser.parse(data)
}
```

Under main-actor-by-default, a parser declared in the same target may also inherit main-actor isolation. If so, mark the existing `Parser.parse` method `nonisolated` (and make any helpers it calls nonisolated too), assuming it doesn’t access main-actor state. If `Item` is a value type, make it `Sendable` and ensure its stored properties are sendable.

In SwiftUI, call it with `.task { await model.load() }`. SwiftUI can then cancel the load when the view disappears. The cancellation check after parsing prevents a cancelled load from publishing results; it doesn’t interrupt the synchronous parser itself.

```swift
import Foundation
import Observation

@Observable
final class FeedModel {
    private(set) var items: [Item] = []
    private(set) var isLoading = false
    private(set) var error: (any Error)?

    private let feedURL: URL

    init(feedURL: URL) {
        self.feedURL = feedURL
    }

    func load() async {
        guard !isLoading, !Task.isCancelled else { return }
        isLoading = true
        error = nil
        defer { isLoading = false }

        do {
            let (data, response) = try await URLSession.shared.data(from: feedURL)
            try Task.checkCancellation()
            if let http = response as? HTTPURLResponse,
               !(200..<300).contains(http.statusCode) {
                throw URLError(.badServerResponse)
            }
            items = Parser.parse(data)
        } catch is CancellationError {
            // Cancellation is not a load failure.
        } catch {
            if !Task.isCancelled {
                self.error = error
            }
        }
    }
}
```

- In SwiftUI, call `.task { await model.load() }` so the view owns the task’s lifetime.
- Main-actor-by-default keeps model state isolated without an explicit annotation; `URLSession` suspends without blocking the UI.
- Parsing stays on the main actor. Move it to an `@concurrent` helper only if profiling shows a hitch.

