  readonly windowSeconds: 60;
}

interface RateLimitStatus {
  readonly limit: number;
  readonly remaining: number;
  readonly resetAtEpochMs: number;
}

type RateLimitDecision =
  | (RateLimitStatus & { readonly allowed: true })
  | (RateLimitStatus & {
      readonly allowed: false;
      readonly retryAfterSeconds: number;
    });

interface RateLimitStore {
  consume(
    keyId: VerifiedApiKeyId,
    policy: RateLimitPolicy,
  ): Promise<RateLimitDecision>;
}

interface RateLimiter {
  checkAndConsume(keyId: VerifiedApiKeyId): Promise<RateLimitDecision>;
}

declare function createRateLimiter(
  store: RateLimitStore,
  policy: RateLimitPolicy,
): RateLimiter;
```

