<body>
  <section id="hud" aria-label="Race information">
    <h1>Meadow Circuit</h1>
    <div>Lap <span id="lap">1</span> · <span id="time">0:00.000</span></div>
    <div>Best · <span id="best">—</span></div>
    <p id="status"></p>
    <p class="controls">WASD / arrows to drive · R to restart</p>
  </section>

  <script type="module">
    import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js';

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0xa6d7ef);
    scene.fog = new THREE.Fog(0xa6d7ef, 95, 210);

    const camera = new THREE.PerspectiveCamera(62, innerWidth / innerHeight, 0.1, 260);
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
    renderer.setSize(innerWidth, innerHeight);
    document.body.appendChild(renderer.domElement);

    scene.add(new THREE.HemisphereLight(0xfff5df, 0x607c54, 2.1));
    const sun = new THREE.DirectionalLight(0xffe0b3, 2.2);
    sun.position.set(-35, 55, -20);
    scene.add(sun);

    function material(color) {
      return new THREE.MeshStandardMaterial({ color, flatShading: true });
    }

    function mesh(geometry, mat, x, y, z, parent = scene) {
      const object = new THREE.Mesh(geometry, mat);
      object.position.set(x, y, z);
      parent.add(object);
      return object;
    }

    function box(w, h, d, mat, x, y, z, parent = scene) {
      return mesh(new THREE.BoxGeometry(w, h, d), mat, x, y, z, parent);
    }

    const A = 42, B = 29, HALF_WIDTH = 5.5, SEGMENTS = 160;
    const TAU = Math.PI * 2;
    const asphalt = material(0x343b46);
    const white = material(0xfff7de);
    const red = material(0xe84440);
    const dark = material(0x171e27);

    box(460, 0.2, 460, material(0x699c51), 0, -0.15, 0);

    // Offset the ellipse along its normal so the road has constant width.
    function trackPoint(t, offset = 0) {
      const c = Math.cos(t), s = Math.sin(t);
      const n = Math.hypot(c / A, s / B);
      return [A * c + offset * c / A / n, B * s + offset * s / B / n];
    }

    function strip(from, to, inner, outer, y, mat, steps) {
      const vertices = [], indices = [];
      for (let i = 0; i <= steps; i++) {
        const t = from + (to - from) * i / steps;
        for (const offset of [inner, outer]) {
          const [x, z] = trackPoint(t, offset);
          vertices.push(x, y, z);
        }
        if (i < steps) {
          const j = i * 2;
          indices.push(j, j + 2, j + 1, j + 1, j + 2, j + 3);
        }
      }
      const geometry = new THREE.BufferGeometry();
      geometry.setAttribute('position', new THREE.Float32BufferAttribute(vertices, 3));
      geometry.setIndex(indices);
      geometry.computeVertexNormals();
      mesh(geometry, mat, 0, 0, 0);
    }

    strip(0, TAU, -HALF_WIDTH, HALF_WIDTH, 0, asphalt, SEGMENTS);
    for (let i = 0; i < 80; i++) {
      const start = TAU * i / 80, end = TAU * (i + 1) / 80;
      const curb = i % 2 ? white : red;
      strip(start, end, -HALF_WIDTH, -HALF_WIDTH + 0.45, 0.025, curb, 2);
      strip(start, end, HALF_WIDTH - 0.45, HALF_WIDTH, 0.025, curb, 2);
      if (i % 2 === 0) {
        strip(start, start + (end - start) * 0.8, -0.065, 0.065, 0.014, white, 2);
      }
    }

    // The start/finish gate is at (A, 0), perpendicular to the driving line.
    for (let row = 0; row < 2; row++) {
      for (let col = 0; col < 14; col++) {
        const w = 2 * HALF_WIDTH / 14;
        box(w, 0.018, 0.42, (row + col) % 2 ? dark : white,
          A - HALF_WIDTH + w * (col + 0.5), 0.03, (row - 0.5) * 0.42);
      }
    }

    // Search nearby samples, then refine to find the distance from the road.
    function distanceToTrack(x, z) {
      const guess = Math.atan2(z / B, x / A);
      const distanceSquared = t => (x - A * Math.cos(t)) ** 2 + (z - B * Math.sin(t)) ** 2;
      let bestAngle = guess, bestDistance = Infinity;
      for (let i = -8; i <= 8; i++) {
        const t = guess + i * 0.1;
        const distance = distanceSquared(t);
        if (distance < bestDistance) {
          bestDistance = distance;
          bestAngle = t;
        }
      }
      let lo = bestAngle - 0.1, hi = bestAngle + 0.1;
      for (let i = 0; i < 12; i++) {
        const left = (2 * lo + hi) / 3, right = (lo + 2 * hi) / 3;
        if (distanceSquared(left) < distanceSquared(right)) hi = right;
        else lo = left;
      }
      return Math.sqrt(distanceSquared((lo + hi) / 2));
    }

    // Deterministic scenery, kept away from the road and its shoulders.
    let seed = 93;
    function random() {
      seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
      return seed / 4294967296;
    }

    const trunks = material(0x735134);
    const leaves = [material(0x275845), material(0x397646), material(0x518b48)];
    const trunkGeo = new THREE.CylinderGeometry(0.2, 0.28, 1.8, 5);
    const crownGeo = new THREE.ConeGeometry(1.4, 3.5, 5);
    for (let i = 0; i < 135; i++) {
      const x = (random() - 0.5) * 180, z = (random() - 0.5) * 150;
      if (distanceToTrack(x, z) < 10) continue;
      const scale = 0.7 + random() * 0.75;
      const tree = new THREE.Group();
      tree.position.set(x, -0.05, z);
      tree.scale.setScalar(scale);
      tree.rotation.y = random() * TAU;
      scene.add(tree);
      mesh(trunkGeo, trunks, 0, 0.9, 0, tree);
      mesh(crownGeo, leaves[i % leaves.length], 0, 2.8, 0, tree);
    }

    const car = new THREE.Group();
    scene.add(car);
    box(1.65, 0.42, 2.8, material(0xf65a29), 0, 0.52, 0, car);
    box(1.2, 0.42, 1.27, material(0x244658), 0, 0.91, -0.2, car);
    box(1.05, 0.04, 1.05, red, 0, 1.14, -0.2, car);
    for (const side of [-1, 1]) {
      box(0.32, 0.16, 0.06, white, side * 0.53, 0.56, 1.42, car);
      box(0.35, 0.14, 0.06, red, side * 0.53, 0.56, -1.42, car);
      for (const axle of [-0.93, 0.93]) {
        const wheel = mesh(new THREE.CylinderGeometry(0.32, 0.32, 0.26, 8),
          dark, side * 0.82, 0.32, axle, car);
        wheel.rotation.z = Math.PI / 2;
