    ]);
    addEventListener('keydown', event => {
      if (!drivingKeys.has(event.code)) return;
      event.preventDefault();
      keys.add(event.code);
      if (event.code === 'KeyR' && !event.repeat) reset();
    });
    addEventListener('keyup', event => keys.delete(event.code));
    addEventListener('blur', () => keys.clear());

    const lapText = document.getElementById('lap');
    const timeText = document.getElementById('time');
    const bestText = document.getElementById('best');
    const statusText = document.getElementById('status');
    const storageKey = 'meadow-circuit-best-v1';
    let best = null;
    try {
      const saved = Number(localStorage.getItem(storageKey));
      if (Number.isFinite(saved) && saved > 0) best = saved;
    } catch { /* The game still works when storage is disabled. */ }

    function format(seconds) {
      const ms = Math.floor(seconds * 1000);
      return `${Math.floor(ms / 60000)}:${String(Math.floor(ms / 1000) % 60).padStart(2, '0')}.${String(ms % 1000).padStart(3, '0')}`;
    }
    bestText.textContent = best === null ? '—' : format(best);

    let x, z, heading, speed, lap, startedAt, nextGate, snapCamera;
    const cameraTarget = new THREE.Vector3();
    const lookTarget = new THREE.Vector3();

    function reset() {
      x = A; z = -4; heading = 0; speed = 0;
      lap = 1; startedAt = null; nextGate = 0; snapCamera = true;
      statusText.textContent = 'Cross the start line to begin';
    }

    function finishCrossing(now) {
      if (startedAt !== null && nextGate === 3) {
        const elapsed = (now - startedAt) / 1000;
        const record = best === null || elapsed < best;
        if (record) {
          best = elapsed;
          bestText.textContent = format(best);
          try { localStorage.setItem(storageKey, String(best)); } catch {}
        }
        lap++;
        statusText.textContent = `${record ? 'New best' : 'Last lap'}: ${format(elapsed)}`;
      } else if (startedAt !== null) {
        statusText.textContent = 'Checkpoint missed · lap restarted';
      } else {
        statusText.textContent = 'Lap in progress';
      }
      startedAt = now;
      nextGate = 0;
    }

    // Ordered, forward-only gates prevent driving back and forth over the stripe
    // from counting as laps. Each crossing must be within the road width.
    function checkGates(oldX, oldZ, now, frameMs) {
      const gates = [
        [oldX, x, oldZ, z, B, -1],   // north end, moving west
        [oldZ, z, oldX, x, -A, -1],  // west end, moving south
        [oldX, x, oldZ, z, -B, 1],   // south end, moving east
        [oldZ, z, oldX, x, A, 1]     // finish, moving north
      ];
      for (let i = 0; i < gates.length; i++) {
        const [before, after, crossBefore, crossAfter, center, direction] = gates[i];
        if (before * direction >= 0 || after * direction < 0) continue;
        const fraction = -before / (after - before);
        const cross = crossBefore + (crossAfter - crossBefore) * fraction;
        if (Math.abs(cross - center) > HALF_WIDTH) continue;
        if (i === 3) finishCrossing(now - frameMs * (1 - fraction));
        else if (startedAt !== null && nextGate === i) nextGate++;
      }
    }

    const pressed = (a, b) => keys.has(a) || keys.has(b);
    const clamp = THREE.MathUtils.clamp;
    let previousTime = null;
    reset();

    function frame(now) {
      const dt = previousTime === null ? 0 : Math.min((now - previousTime) / 1000, 0.05);
      previousTime = now;

      const throttle = Number(pressed('KeyW', 'ArrowUp')) - Number(pressed('KeyS', 'ArrowDown'));
      const steer = Number(pressed('KeyA', 'ArrowLeft')) - Number(pressed('KeyD', 'ArrowRight'));
      const offRoad = distanceToTrack(x, z) > HALF_WIDTH;
      const cap = offRoad ? 9 : 30;

      if (throttle) {
        const braking = speed * throttle < 0;
        speed += throttle * (braking ? 33 : throttle > 0 ? 16 : 9) * dt;
      }
      speed *= Math.exp(-(offRoad ? 1.45 : throttle ? 0.25 : 0.85) * dt);
      speed = clamp(speed, -8, 30);
      if (speed > cap) speed = Math.max(cap, speed - 22 * dt);
      if (Math.abs(speed) < 0.04 && !throttle) speed = 0;

      heading += steer * Math.sign(speed) * 1.9 * Math.min(Math.abs(speed) / 6, 1) * dt;
      const fx = Math.sin(heading), fz = Math.cos(heading);
      const oldX = x, oldZ = z;
      x += fx * speed * dt;
      z += fz * speed * dt;

      // Let the player recover from a long excursion without getting lost.
      if (Math.abs(x) > 100 || Math.abs(z) > 85) reset();
      else checkGates(oldX, oldZ, now, dt * 1000);

      car.position.set(x, 0.04, z);
      car.rotation.y = heading;
      shadow.position.set(x, 0.009, z);
      shadow.rotation.z = -heading;

      const forwardX = Math.sin(heading), forwardZ = Math.cos(heading);
      cameraTarget.set(x - forwardX * 8, 5.6, z - forwardZ * 8);
      lookTarget.set(x + forwardX * 4, 0.65, z + forwardZ * 4);
      if (snapCamera) {
        camera.position.copy(cameraTarget);
        snapCamera = false;
      } else {
        camera.position.lerp(cameraTarget, 1 - Math.exp(-7 * dt));
      }
      camera.lookAt(lookTarget);

      lapText.textContent = lap;
      timeText.textContent = format(startedAt === null ? 0 : Math.max(0, now - startedAt) / 1000);
      renderer.render(scene, camera);
      requestAnimationFrame(frame);
    }

    addEventListener('resize', () => {
      camera.aspect = innerWidth / innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(innerWidth, innerHeight);
    });
    requestAnimationFrame(frame);
  </script>
</body>
</html>
