ribbon(-halfRoad, halfRoad, 0.02, [0x353d46], () => 0);
ribbon(-0.055, 0.055, 0.032, [0xf4cf81], i => i % 9 < 4 ? 0 : -1);
for (const sign of [-1, 1]) {
  const edge = sign * halfRoad;
  ribbon(edge - 0.20, edge + 0.20, 0.035, [0xf0e5ce, 0xbf4b39],
         i => Math.floor(i / 3) % 2);
