const finish = trackFrame(0);
const tileWidth = 2 * halfRoad / 12;
const tile = new THREE.BoxGeometry(tileWidth, 0.018, 0.55);
const finishColors = [material(0xfff8e7), material(0x202730)];
for (let row = 0; row < 2; row++) {
