### `ReportExport.tsx`

```tsx
"use client";

import { useRef, useState } from "react";

type Cell = string | number | boolean | null | undefined;
type Format = "csv" | "xlsx" | "pdf";

export type ExportColumn<Row> = {
  header: string;
  value: (row: Row) => Cell;
};

type Props<Row> = {
  rows: readonly Row[];
  columns: readonly ExportColumn<Row>[];
  filename?: string; // Base name, without an extension
};

const formats: Format[] = ["csv", "xlsx", "pdf"];

function download(blob: Blob, filename: string) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 30_000);
}

function csvField(value: Cell) {
  let text = String(value ?? "");

  // Quoting alone does not prevent spreadsheet formula interpretation.
  // Apply this to text only so negative numeric values stay numeric.
  if (
    typeof value === "string" &&
    /^(?:[\t\r\n]|\s*[=+\-@＝＋－＠])/u.test(text)
  ) {
    text = `'${text}`;
  }

  return `"${text.replace(/"/g, '""')}"`;
}

export function ReportExport<Row>({
  rows,
  columns,
  filename = "report",
}: Props<Row>) {
  const inProgress = useRef(false);
  const [busy, setBusy] = useState<Format | null>(null);
  const [error, setError] = useState("");

  async function exportReport(format: Format) {
    if (inProgress.current || !rows.length || !columns.length) return;

    inProgress.current = true;
    setBusy(format);
    setError("");

    try {
      const headers = columns.map((column) => column.header);
      const data = rows.map((row) =>
        columns.map((column) => column.value(row) ?? null),
      );
      const outputName = `${filename}.${format}`;

      if (format === "csv") {
        const csv = [headers, ...data]
          .map((row) => row.map(csvField).join(","))
          .join("\r\n");

        // The BOM helps Excel recognize UTF-8 when opening the CSV.
        download(new Blob(["\uFEFF", csv], { type: "text/csv;charset=utf-8" }), outputName);
      } else if (format === "xlsx") {
        const { default: ExcelJS } = await import("exceljs");
        const workbook = new ExcelJS.Workbook();
        const sheet = workbook.addWorksheet("Report", {
          views: [{ state: "frozen", ySplit: 1 }],
        });

        sheet.addRow(headers).font = { bold: true };
        sheet.addRows(data);
        headers.forEach((header, index) => {
          sheet.getColumn(index + 1).width = Math.min(
            40,
            Math.max(14, header.length + 4),
          );
        });

        const buffer = await workbook.xlsx.writeBuffer();
        download(
          new Blob([buffer], {
            type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
          }),
          outputName,
        );
      } else {
        const [{ jsPDF }, { autoTable }] = await Promise.all([
          import("jspdf"),
          import("jspdf-autotable"),
        ]);

        const doc = new jsPDF({
          orientation: "landscape",
          unit: "pt",
          format: "a4",
        });

        autoTable(doc, {
          head: [headers],
          body: data.map((row) => row.map((value) => String(value ?? ""))),
          showHead: "everyPage",
          horizontalPageBreak: true,
          styles: { fontSize: 9, overflow: "linebreak" },
        });

        doc.save(outputName);
      }
    } catch (err) {
      console.error(`Report ${format} export failed`, err);
      setError(`Could not export ${format.toUpperCase()}. Please try again.`);
    } finally {
      inProgress.current = false;
      setBusy(null);
    }
  }

  return (
    <div role="group" aria-label="Export report" aria-busy={busy !== null}>
      {formats.map((format) => (
        <button
          key={format}
          type="button"
          disabled={busy !== null || !rows.length || !columns.length}
          onClick={() => void exportReport(format)}
        >
          {busy === format
            ? `Exporting ${format.toUpperCase()}…`
            : `Export ${format.toUpperCase()}`}
        </button>
      ))}
      {error && <p role="alert">{error}</p>}
    </div>
  );
}
```

