Use `exceljs` for CSV and XLSX, and `jspdf` with `jspdf-autotable` for PDF. The component below exports all rows you pass it, in the column order you specify. Add `jspdf` and `jspdf-autotable` to your dependencies; CSV and XLSX use the `exceljs` dependency you already have.

```tsx
// components/ReportExport.tsx
'use client';

import { useState } from 'react';

type Format = 'csv' | 'xlsx' | 'pdf';
type Cell = string | number | boolean | Date | null | undefined;

export type ExportColumn<Row> = {
  header: string;
  value: (row: Row) => Cell;
};

type Props<Row> = {
  rows: readonly Row[];
  columns: readonly ExportColumn<Row>[];
  filename?: string; // Base name, without an extension
  title?: string;
};

function display(value: Cell): string {
  if (value == null) return '';
  if (value instanceof Date) {
    return Number.isNaN(value.getTime()) ? '' : value.toISOString();
  }
  return String(value);
}

function csvCell(value: Cell): string {
  // Quoting CSV fields alone does not prevent spreadsheet formula injection.
  if (
    typeof value === 'string' &&
    (/^[\s\uFEFF]*[=+\-@]/u.test(value) || /^[\t\r\n]/u.test(value))
  ) {
    return `'${value}`;
  }
  return display(value);
}

function download(blob: Blob, filename: string) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 60_000);
}

// Copy ExcelJS's output into an ArrayBuffer suitable for a browser Blob.
function toArrayBuffer(bytes: ArrayLike<number>): ArrayBuffer {
  const buffer = new ArrayBuffer(bytes.length);
  new Uint8Array(buffer).set(bytes);
  return buffer;
}

export function ReportExport<Row>({
  rows,
  columns,
  filename = 'report',
  title = 'Report',
}: Props<Row>) {
  const [busy, setBusy] = useState<Format | null>(null);
  const [error, setError] = useState('');

  async function exportReport(format: Format) {
    setBusy(format);
    setError('');

    try {
      const headers = columns.map((column) => column.header);
      const data = rows.map((row) => columns.map((column) => column.value(row)));
      const name = `${filename}.${format}`;

      if (format === 'pdf') {
        const [{ jsPDF }, { autoTable }] = await Promise.all([
          import('jspdf'),
          import('jspdf-autotable'),
        ]);
        const doc = new jsPDF({
          orientation: columns.length > 5 ? 'landscape' : 'portrait',
        });
        doc.text(title, 14, 16);
        autoTable(doc, {
          startY: 22,
          head: [headers],
          body: data.map((row) => row.map(display)),
          showHead: 'everyPage',
          styles: { fontSize: 9, overflow: 'linebreak' },
        });
        doc.save(name);
        return;
      }

      const { default: ExcelJS } = await import('exceljs');
      const workbook = new ExcelJS.Workbook();
      const sheet = workbook.addWorksheet('Report');

      if (format === 'csv') {
        sheet.addRow(headers.map(csvCell));
        for (const row of data) sheet.addRow(row.map(csvCell));

        const bytes = await workbook.csv.writeBuffer({
          formatterOptions: { writeBOM: true },
        });
        download(
          new Blob([toArrayBuffer(bytes)], { type: 'text/csv;charset=utf-8' }),
          name,
        );
      } else {
        sheet.addRow(headers).font = { bold: true };
        sheet.views = [{ state: 'frozen', ySplit: 1 }];
        sheet.columns.forEach((column, i) => {
          column.width = Math.min(40, Math.max(14, headers[i].length + 4));
        });

        for (const row of data) {
          // Strings remain text cells; numbers and booleans retain their types.
          sheet.addRow(row.map((value) => (
            value instanceof Date ? display(value) : value ?? null
          )));
        }

        const bytes = await workbook.xlsx.writeBuffer();
        download(
          new Blob([toArrayBuffer(bytes)], {
            type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
          }),
          name,
        );
      }
    } catch (cause) {
      console.error(`Report ${format.toUpperCase()} export failed`, cause);
      setError(`Could not export ${format.toUpperCase()}. Please try again.`);
    } finally {
      setBusy(null);
    }
  }

  return (
    <div role="group" aria-label="Export report">
      {(['csv', 'xlsx', 'pdf'] as const).map((format) => (
        <button
          key={format}
          type="button"
          disabled={busy !== null || columns.length === 0}
          onClick={() => void exportReport(format)}
        >
