Add a client-side export component and pass it the same rows and columns you render in the reports table. CSV and XLSX use your existing `exceljs` dependency. PDF uses `jspdf` and `jspdf-autotable`; add those two packages to your app’s dependencies.

```tsx
// components/ReportExport.tsx
'use client';

import { useState } from 'react';

type Cell = string | number | boolean | null | undefined;

export type ExportColumn<Row> = {
  header: string;
  value: (row: Row) => Cell;
};

type Format = 'csv' | 'xlsx' | 'pdf';

function download(blob: Blob, filename: string) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  // Give the browser time to start the download before releasing the URL.
  window.setTimeout(() => URL.revokeObjectURL(url), 30_000);
}

function csvSafe(value: Cell): Cell {
  // Spreadsheet apps can interpret CSV text as formulas. Keep actual numbers
  // numeric, but prefix formula-like strings with an apostrophe.
  return typeof value === 'string' &&
    /^(?:[\t\r\n]|\s*[=+\-@＝＋－＠])/u.test(value)
    ? `'${value}`
    : value;
}

export function ReportExport<Row>({
  rows,
  columns,
  filename = 'report',
}: {
  rows: readonly Row[];
  columns: readonly ExportColumn<Row>[];
  filename?: string;
}) {
  const [busy, setBusy] = useState<Format | null>(null);
  const [error, setError] = useState('');

  async function exportReport(format: Format) {
    setBusy(format);
    setError('');

    try {
      const headers = columns.map((column) => column.header);
      const data = rows.map((row) =>
        columns.map((column) => column.value(row) ?? null),
      );

      if (format === 'pdf') {
        const [{ jsPDF }, { autoTable }] = await Promise.all([
          import('jspdf'),
          import('jspdf-autotable'),
        ]);

        const doc = new jsPDF({ orientation: 'landscape' });
        autoTable(doc, {
          head: [headers],
          body: data.map((row) => row.map((value) => String(value ?? ''))),
          styles: { fontSize: 8, overflow: 'linebreak' },
          horizontalPageBreak: true,
          showHead: 'everyPage',
        });
        download(doc.output('blob'), `${filename}.pdf`);
        return;
      }

      const { Workbook } = await import('exceljs');
      const workbook = new Workbook();
      const sheet = workbook.addWorksheet('Report');
      const records = [headers, ...data];

      for (const row of records) {
        sheet.addRow(format === 'csv' ? row.map(csvSafe) : row);
      }

      if (format === 'csv') {
        const bytes = await workbook.csv.writeBuffer({
          sheetName: sheet.name,
          formatterOptions: { writeBOM: true },
        });
        download(
          new Blob([new Uint8Array(bytes)], { type: 'text/csv;charset=utf-8' }),
          `${filename}.csv`,
        );
      } else {
        sheet.getRow(1).font = { bold: true };
        sheet.views = [{ state: 'frozen', ySplit: 1 }];

        const bytes = await workbook.xlsx.writeBuffer();
        download(
          new Blob([new Uint8Array(bytes)], {
            type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
          }),
          `${filename}.xlsx`,
        );
      }
    } catch (cause) {
      console.error(`Failed to export ${format}`, cause);
      setError(`Could not export ${format.toUpperCase()}. Please try again.`);
    } finally {
      setBusy(null);
    }
  }

  return (
    <div role="group" aria-label="Export report" aria-busy={busy !== null}>
      {(['csv', 'xlsx', 'pdf'] as const).map((format) => (
        <button
          key={format}
          type="button"
          disabled={busy !== null || columns.length === 0}
          onClick={() => void exportReport(format)}
        >
          {busy === format
            ? `Exporting ${format.toUpperCase()}…`
            : `Export ${format.toUpperCase()}`}
        </button>
      ))}
      {error && <p role="alert">{error}</p>}
    </div>
  );
}
```

